import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
  inOutEnvelope,
} from "../motion";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 12;

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ============================================================
// SCENE 1 — Hero headline: "Actors — built for agents"
// ============================================================
const SCENE_ONE_DURATION = 75;

const SceneOne: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const envelope = inOutEnvelope(frame, vfps, SCENE_ONE_DURATION);

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const titleIn = springIn(frame, vfps, 10, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 22, "LIQUID");
  const tailIn = springIn(frame, vfps, 18, "SNAPPY");
  const ruleIn = springIn(frame, vfps, 34, "LIQUID");

  const driftY = ambientDrift(frame, 3, 120, "hero-y");
  const driftX = ambientDrift(frame, 2, 140, "hero-x");

  const headlineSize = base * 0.095;
  const eyebrowSize = base * 0.022;

  return (
    <AbsoluteFill
      style={{
        background: COLORS.bg,
        opacity: envelope,
        fontFamily: BRAND.fonts.marketing,
      }}
    >
      <Background />

      {/* Off-center anchored hero — left aligned, vertically centered */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "30%",
          maxWidth: "78%",
          transform: `translate(${driftX}px, ${driftY}px)`,
        }}
      >
        {/* Eyebrow label */}
        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: eyebrowSize,
            color: COLORS.orange,
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            marginBottom: base * 0.028,
            opacity: eyebrowIn,
            transform: `translateY(${interpolate(eyebrowIn, [0, 1], [12, 0])}px)`,
          }}
        >
          Introducing
        </div>

        {/* Headline line */}
        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: headlineSize,
            color: COLORS.text,
            letterSpacing: "-0.03em",
            lineHeight: 1.02,
          }}
        >
          <span
            style={{
              display: "inline-block",
              opacity: titleIn,
              transform: `translateY(${interpolate(titleIn, [0, 1], [40, 0])}px) scale(${interpolate(titleIn, [0, 1], [0.94, 1])})`,
              filter: `blur(${interpolate(titleIn, [0, 1], [10, 0])}px)`,
            }}
          >
            <span
              style={{
                background: COLORS.orangeTint,
                borderBottom: `${Math.max(2, base * 0.0035)}px solid ${COLORS.orange}`,
                padding: `0 ${base * 0.014}px`,
                borderRadius: base * 0.008,
                clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
              }}
            >
              Actors
            </span>
          </span>
          <span
            style={{
              display: "inline-block",
              marginLeft: base * 0.018,
              opacity: tailIn,
              transform: `translateY(${interpolate(tailIn, [0, 1], [40, 0])}px)`,
              filter: `blur(${interpolate(tailIn, [0, 1], [10, 0])}px)`,
            }}
          >
            — built for agents.
          </span>
        </div>

        {/* Thin orange accent rule */}
        <div
          style={{
            marginTop: base * 0.04,
            height: Math.max(2, base * 0.003),
            background: COLORS.orange,
            width: `${interpolate(ruleIn, [0, 1], [0, 28])}%`,
            opacity: ruleIn,
            borderRadius: 999,
          }}
        />

        {/* Subhead */}
        <div
          style={{
            marginTop: base * 0.028,
            fontFamily: BRAND.fonts.primary,
            fontWeight: 400,
            fontSize: base * 0.024,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            lineHeight: 1.35,
            maxWidth: "60%",
            opacity: ruleIn,
            transform: `translateY(${interpolate(ruleIn, [0, 1], [14, 0])}px)`,
          }}
        >
          Production-grade workers your LLM can call, schedule, and chain.
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 2 — Trigger → Actor → Output flow diagram
// ============================================================
const SCENE_TWO_DURATION = 90;

type Node = {
  label: string;
  caption: string;
  icon: "trigger" | "actor" | "output";
};

const NODES: Node[] = [
  { label: "Trigger", caption: "Agent calls", icon: "trigger" },
  { label: "Actor", caption: "Runs on Apify", icon: "actor" },
  { label: "Output", caption: "Structured data", icon: "output" },
];

const NodeIcon: React.FC<{ kind: Node["icon"]; size: number }> = ({
  kind,
  size,
}) => {
  const stroke = COLORS.orange;
  const sw = Math.max(2.5, size * 0.05);
  if (kind === "trigger") {
    return (
      <svg width={size} height={size} viewBox="0 0 24 24">
        <path
          d="M13 2 L4 14 L11 14 L10 22 L20 9 L13 9 Z"
          fill="none"
          stroke={stroke}
          strokeWidth={sw}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    );
  }
  if (kind === "actor") {
    return (
      <svg width={size} height={size} viewBox="0 0 24 24">
        <rect
          x={3}
          y={3}
          width={18}
          height={18}
          rx={4}
          fill="none"
          stroke={stroke}
          strokeWidth={sw}
        />
        <circle cx={9} cy={10} r={1.5} fill={stroke} />
        <circle cx={15} cy={10} r={1.5} fill={stroke} />
        <path
          d="M8 15 L16 15"
          stroke={stroke}
          strokeWidth={sw}
          strokeLinecap="round"
        />
      </svg>
    );
  }
  return (
    <svg width={size} height={size} viewBox="0 0 24 24">
      <path
        d="M4 7 H20 M4 12 H20 M4 17 H14"
        stroke={stroke}
        strokeWidth={sw}
        strokeLinecap="round"
      />
    </svg>
  );
};

const SceneTwo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const envelope = inOutEnvelope(frame, vfps, SCENE_TWO_DURATION);

  const headerIn = springIn(frame, vfps, 4, "SNAPPY");
  const headerDrift = ambientDrift(frame, 2, 100, "header-drift");

  const nodeSize = base * 0.14;
  const gap = base * 0.085;
  const totalRowWidth = nodeSize * 3 + gap * 2;

  // Line draw progress — draws left to right
  const lineDraw = springIn(frame, vfps, 20, "LIQUID");

  const headerSize = base * 0.045;
  const eyebrowSize = base * 0.018;

  return (
    <AbsoluteFill
      style={{
        background: COLORS.bg,
        opacity: envelope,
        fontFamily: BRAND.fonts.marketing,
      }}
    >
      <Background />

      {/* Header — anchored top-left of content column */}
      <div
        style={{
          position: "absolute",
          top: "18%",
          left: "9%",
          opacity: headerIn,
          transform: `translateY(${interpolate(headerIn, [0, 1], [16, 0]) + headerDrift}px)`,
        }}
      >
        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: eyebrowSize,
            color: COLORS.orange,
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            marginBottom: base * 0.014,
          }}
        >
          How it works
        </div>
        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: headerSize,
            color: COLORS.text,
            letterSpacing: "-0.025em",
            lineHeight: 1.08,
            maxWidth: width * 0.55,
          }}
        >
          One{" "}
          <span
            style={{
              background: COLORS.orangeTint,
              borderBottom: `${Math.max(2, base * 0.003)}px solid ${COLORS.orange}`,
              padding: `0 ${base * 0.01}px`,
              borderRadius: base * 0.006,
            }}
          >
            call
          </span>
          , one Actor, one structured result.
        </div>
      </div>

      {/* Diagram row — horizontally centered, vertically lower-middle */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "58%",
          transform: "translate(-50%, -50%)",
          width: totalRowWidth,
          height: nodeSize * 1.7,
        }}
      >
        {/* Connecting line — sits behind nodes */}
        <svg
          width={totalRowWidth}
          height={nodeSize}
          viewBox={`0 0 ${totalRowWidth} ${nodeSize}`}
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            overflow: "visible",
          }}
        >
          {(() => {
            const cy = nodeSize / 2;
            const x1 = nodeSize / 2;
            const x2 = totalRowWidth - nodeSize / 2;
            const totalLen = x2 - x1;
            const dashOffset = interpolate(lineDraw, [0, 1], [totalLen, 0]);
            return (
              <>
                <line
                  x1={x1}
                  y1={cy}
                  x2={x2}
                  y2={cy}
                  stroke={COLORS.border}
                  strokeWidth={1.5}
                  strokeDasharray="4 6"
                  opacity={0.6}
                />
                <line
                  x1={x1}
                  y1={cy}
                  x2={x2}
                  y2={cy}
                  stroke={COLORS.orange}
                  strokeWidth={Math.max(2, base * 0.0035)}
                  strokeLinecap="round"
                  strokeDasharray={totalLen}
                  strokeDashoffset={dashOffset}
                />
                {/* Arrow tips at the right end as the line completes */}
                <g
                  opacity={interpolate(lineDraw, [0.85, 1], [0, 1], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  })}
                  transform={`translate(${x2 - 8}, ${cy})`}
                >
                  <path
                    d="M -10 -6 L 0 0 L -10 6"
                    fill="none"
                    stroke={COLORS.orange}
                    strokeWidth={Math.max(2, base * 0.0035)}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </g>
              </>
            );
          })()}
        </svg>

        {/* Nodes */}
        {NODES.map((node, i) => {
          const nodeIn = staggeredSpring(
            frame,
            vfps,
            i,
            14,
            14,
            "ELASTIC"
          );
          const breathe = ambientDrift(frame, 2, 80 + i * 13, `node-${i}`);
          const x = i * (nodeSize + gap);

          const ringPulse = interpolate(
            frame,
            [
              14 + i * 14,
              22 + i * 14,
              36 + i * 14,
            ],
            [0, 1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={node.label}
              style={{
                position: "absolute",
                top: 0,
                left: x,
                width: nodeSize,
                opacity: nodeIn,
                transform: `translateY(${interpolate(nodeIn, [0, 1], [20, 0]) + breathe}px) scale(${interpolate(nodeIn, [0, 1], [0.7, 1])})`,
              }}
            >
              {/* Pulse ring */}
              <div
                style={{
                  position: "absolute",
                  top: -nodeSize * 0.1,
                  left: -nodeSize * 0.1,
                  width: nodeSize * 1.2,
                  height: nodeSize * 1.2,
                  borderRadius: "50%",
                  border: `1.5px solid ${COLORS.orange}`,
                  opacity: ringPulse * 0.5,
                  transform: `scale(${interpolate(ringPulse, [0, 1], [0.9, 1.15])})`,
                }}
              />

              {/* Circular node */}
              <div
                style={{
                  width: nodeSize,
                  height: nodeSize,
                  borderRadius: "50%",
                  background: COLORS.card,
                  border: `1.5px solid ${COLORS.border}`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  boxShadow: `inset 0 0 0 1px rgba(255,255,255,0.02), 0 12px 32px rgba(0,0,0,0.4)`,
                }}
              >
                <NodeIcon kind={node.icon} size={nodeSize * 0.4} />
              </div>

              {/* Labels below node */}
              <div
                style={{
                  marginTop: base * 0.024,
                  textAlign: "center",
                  fontFamily: BRAND.fonts.marketing,
                  fontWeight: 600,
                  fontSize: base * 0.026,
                  color: COLORS.text,
                  letterSpacing: "-0.01em",
                }}
              >
                {node.label}
              </div>
              <div
                style={{
                  marginTop: base * 0.006,
                  textAlign: "center",
                  fontFamily: BRAND.fonts.primary,
                  fontWeight: 400,
                  fontSize: base * 0.017,
                  color: COLORS.textMuted,
                  letterSpacing: "0",
                }}
              >
                {node.caption}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 3 — Tagline: "Build. Run. Scale."
// ============================================================
const SCENE_THREE_DURATION = 60;

const TAGLINE_WORDS = ["Build.", "Run.", "Scale."];

const SceneThree: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const envelope = inOutEnvelope(frame, vfps, SCENE_THREE_DURATION);

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const ruleIn = springIn(frame, vfps, 36, "LIQUID");

  const groupDriftY = ambientDrift(frame, 2.5, 110, "tagline-y");

  const wordSize = base * 0.11;

  return (
    <AbsoluteFill
      style={{
        background: COLORS.bg,
        opacity: envelope,
        fontFamily: BRAND.fonts.marketing,
      }}
    >
      <Background />

      {/* Anchored slightly left and lower-third */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "34%",
          maxWidth: "82%",
          transform: `translateY(${groupDriftY}px)`,
        }}
      >
        <div
          style={{
            fontFamily: BRAND.fonts.marketing,
            fontWeight: 600,
            fontSize: base * 0.022,
            color: COLORS.orange,
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            marginBottom: base * 0.026,
            opacity: eyebrowIn,
            transform: `translateY(${interpolate(eyebrowIn, [0, 1], [10, 0])}px)`,
          }}
        >
          The Apify way
        </div>

        {/* Tagline — each word with its own preset and stagger */}
        <div
          style={{
            display: "flex",
            gap: base * 0.026,
            flexWrap: "wrap",
            alignItems: "baseline",
          }}
        >
          {TAGLINE_WORDS.map((word, i) => {
            const wordIn = staggeredSpring(
              frame,
              vfps,
              i,
              8,
              10,
              i === 2 ? "LIQUID" : "SNAPPY"
            );
            const isAccent = i === 2;
            return (
              <span
                key={word}
                style={{
                  display: "inline-block",
                  fontFamily: BRAND.fonts.marketing,
                  fontWeight: 600,
                  fontSize: wordSize,
                  color: isAccent ? COLORS.text : COLORS.text,
                  letterSpacing: "-0.03em",
                  lineHeight: 1,
                  opacity: wordIn,
                  transform: `translateY(${interpolate(wordIn, [0, 1], [50, 0])}px) scale(${interpolate(wordIn, [0, 1], [0.9, 1])})`,
                  filter: `blur(${interpolate(wordIn, [0, 1], [10, 0])}px)`,
                }}
              >
                {isAccent ? (
                  <span
                    style={{
                      background: COLORS.orangeTint,
                      borderBottom: `${Math.max(2, base * 0.0035)}px solid ${COLORS.orange}`,
                      padding: `0 ${base * 0.014}px`,
                      borderRadius: base * 0.008,
                    }}
                  >
                    {word}
                  </span>
                ) : (
                  word
                )}
              </span>
            );
          })}
        </div>

        {/* Orange rule + caption */}
        <div
          style={{
            marginTop: base * 0.04,
            height: Math.max(2, base * 0.003),
            background: COLORS.orange,
            width: `${interpolate(ruleIn, [0, 1], [0, 22])}%`,
            opacity: ruleIn,
            borderRadius: 999,
          }}
        />
        <div
          style={{
            marginTop: base * 0.024,
            fontFamily: BRAND.fonts.primary,
            fontWeight: 400,
            fontSize: base * 0.022,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            opacity: ruleIn,
            transform: `translateY(${interpolate(ruleIn, [0, 1], [12, 0])}px)`,
            maxWidth: "55%",
          }}
        >
          Ship agent-ready workers in minutes — not weeks.
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ============================================================
// MAIN COMPOSITION
// ============================================================
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_ONE_DURATION + TRANSITION}>
        <SceneOne />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_TWO_DURATION + TRANSITION}>
        <SceneTwo />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_THREE_DURATION}>
        <SceneThree />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

// Total = (75 + 12) + (90 + 12) + 60 - 12 - 12 = 225
export const durationInFrames =
  SCENE_ONE_DURATION + SCENE_TWO_DURATION + SCENE_THREE_DURATION;

export default MainComposition;
